    private static double constant(MaterialProperty p){MaterialPropertyMethod m=p.getMethod();if(!(m instanceof ConstantMaterialPropertyMethod))throw new IllegalStateException("constant material method required: "+m.getClass().getName());double x=((ConstantMaterialPropertyMethod)m).getQuantity().getSIValue();if(!(x>0)||!Double.isFinite(x))throw new IllegalStateException("invalid material constant");return x;}
    private static Units dimensionless(Simulation s){Dimensions dims=new Dimensions();if(!dims.isDimensionless())throw new IllegalStateException("dimensionless dimensions unavailable");Units u=s.getUnitsManager().getPreferredUnits(dims);if(u==null||!u.getDimensions().isDimensionless())throw new IllegalStateException("native dimensionless units unavailable");return u;}
    private static String cpSIUnitSuffix="UNVERIFIED";
